-- Isolated HeadHunter Preview only. No production data or source URL grants.
begin;
create table public.platform_admins(user_id uuid primary key references auth.users);
alter table public.platform_admins enable row level security;
revoke all on public.platform_admins from anon,authenticated;
create function public.is_platform_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.platform_admins where user_id=auth.uid())$$;
revoke all on function public.is_platform_admin() from public,anon;grant execute on function public.is_platform_admin() to authenticated;
alter table public.jobs add column responsibilities text not null default '' check(length(responsibilities)<=12000),add column requirements text not null default '' check(length(requirements)<=12000),add column benefits text not null default '' check(length(benefits)<=8000);
grant update(responsibilities,requirements,benefits) on public.jobs to authenticated;
alter table public.candidate_profiles add column skills text not null default '' check(length(skills)<=2000),add column experience text not null default '' check(length(experience)<=8000),add column education text not null default '' check(length(education)<=4000),add column preferred_location text not null default '' check(length(preferred_location)<=240);
alter table public.applications alter column job_id drop not null;
alter table public.applications add column external_job_id uuid references public.external_jobs,add constraint exactly_one_job check(num_nonnulls(job_id,external_job_id)=1),add constraint unique_external_application unique(external_job_id,candidate_id);
grant insert(external_job_id) on public.applications to authenticated;
create function public.can_manage_application(app uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.applications where id=app and (public.owns_job(job_id) or (external_job_id is not null and public.is_platform_admin())))$$;
revoke all on function public.can_manage_application(uuid) from public,anon;grant execute on function public.can_manage_application(uuid) to authenticated;
drop policy applications_read on public.applications;
create policy applications_read on public.applications for select to authenticated using(candidate_id=auth.uid() or public.owns_job(job_id) or (external_job_id is not null and public.is_platform_admin()));
drop policy applications_insert on public.applications;
create policy applications_insert on public.applications for insert to authenticated with check(candidate_id=auth.uid() and status='submitted' and ((job_id is not null and exists(select 1 from public.jobs where id=job_id and status='open') and not public.owns_job(job_id)) or (external_job_id is not null and exists(select 1 from public.external_jobs where id=external_job_id and status='active' and publication_status='published'))));
drop policy applications_update on public.applications;
create policy applications_update on public.applications for update to authenticated using(public.can_manage_application(id)) with check(public.can_manage_application(id));
drop policy interview_insert on public.interviews;drop policy interview_read on public.interviews;
create policy interview_read on public.interviews for select to authenticated using(exists(select 1 from public.applications a where a.id=application_id and (a.candidate_id=auth.uid() or public.can_manage_application(a.id))));
create policy interview_insert on public.interviews for insert to authenticated with check(public.can_manage_application(application_id));
create policy platform_profile_read on public.candidate_profiles for select to authenticated using(public.is_platform_admin() and exists(select 1 from public.applications where candidate_id=user_id and external_job_id is not null));
create policy platform_cv_read on storage.objects for select to authenticated using(bucket_id='candidate-cvs' and public.is_platform_admin() and exists(select 1 from public.applications a where a.candidate_id::text=(storage.foldername(name))[1] and a.external_job_id is not null));
create table public.saved_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,job_id uuid references public.jobs,external_job_id uuid references public.external_jobs,created_at timestamptz not null default now(),check(num_nonnulls(job_id,external_job_id)=1),unique(user_id,job_id),unique(user_id,external_job_id));
alter table public.saved_jobs enable row level security;
create policy saved_read on public.saved_jobs for select to authenticated using(user_id=auth.uid());
create policy saved_insert on public.saved_jobs for insert to authenticated with check(user_id=auth.uid() and ((job_id is not null and exists(select 1 from public.jobs where id=job_id and status='open')) or (external_job_id is not null and exists(select 1 from public.external_jobs where id=external_job_id))));
create policy saved_delete on public.saved_jobs for delete to authenticated using(user_id=auth.uid());
revoke all on public.saved_jobs from anon,authenticated;grant select,insert,delete on public.saved_jobs to authenticated;
create table public.recruitment_tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,created_by uuid not null references auth.users,title text not null check(length(trim(title)) between 1 and 240),due_date date,done boolean not null default false,created_at timestamptz not null default now());
alter table public.recruitment_tasks enable row level security;
create policy task_read on public.recruitment_tasks for select to authenticated using(public.has_role(organization_id,array['owner','admin','recruiter','viewer']));
create policy task_insert on public.recruitment_tasks for insert to authenticated with check(created_by=auth.uid() and public.has_role(organization_id,array['owner','admin','recruiter']));
create policy task_update on public.recruitment_tasks for update to authenticated using(public.has_role(organization_id,array['owner','admin','recruiter'])) with check(public.has_role(organization_id,array['owner','admin','recruiter']));
revoke all on public.recruitment_tasks from anon,authenticated;grant select,insert on public.recruitment_tasks to authenticated;grant update(done,title,due_date) on public.recruitment_tasks to authenticated;
create table public.application_activity(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications,kind text not null,status text,created_at timestamptz not null default now());
alter table public.application_activity enable row level security;
create policy activity_read on public.application_activity for select to authenticated using(exists(select 1 from public.applications a where a.id=application_id and (a.candidate_id=auth.uid() or public.can_manage_application(a.id))));
revoke all on public.application_activity from anon,authenticated;grant select on public.application_activity to authenticated;
create function public.log_application_activity() returns trigger language plpgsql security definer set search_path='' as $$begin
 if TG_OP='INSERT' then insert into public.application_activity(application_id,kind,status) values(new.id,'submitted',new.status);elsif old.status<>new.status then insert into public.application_activity(application_id,kind,status) values(new.id,'status_changed',new.status);end if;return new;end$$;
create trigger log_application_activity after insert or update on public.applications for each row execute function public.log_application_activity();
create table public.application_messages(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications,author_id uuid not null references auth.users,body text not null check(length(trim(body)) between 1 and 4000),created_at timestamptz not null default now());
alter table public.application_messages enable row level security;
create policy message_read on public.application_messages for select to authenticated using(exists(select 1 from public.applications a where a.id=application_id and (a.candidate_id=auth.uid() or public.can_manage_application(a.id))));
create policy message_insert on public.application_messages for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from public.applications a where a.id=application_id and (a.candidate_id=auth.uid() or public.can_manage_application(a.id))));
revoke all on public.application_messages from anon,authenticated;grant select,insert on public.application_messages to authenticated;
create function public.platform_overview() returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if not public.is_platform_admin() then raise exception 'Not permitted';end if;
 return jsonb_build_object('organizations',(select count(*) from public.organizations),'candidates',(select count(*) from public.candidate_profiles),'jobs',(select count(*) from public.jobs where status='open'),'imported',(select count(*) from public.external_jobs where publication_status='published' and status='active'),'applications',(select count(*) from public.applications),'imports',(select coalesce(jsonb_agg(x),'[]'::jsonb) from (select s.company,count(e.id) as jobs,max(e.verified_at) as checked_at from public.job_sources s left join public.external_jobs e on e.source_id=s.id group by s.company)x));end$$;
revoke all on function public.platform_overview() from public,anon;grant execute on function public.platform_overview() to authenticated;
commit;
